head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > M > validate]<br/>컴포넌트의 입력값에 대한 유효성 체크를 실행합니다.",
    "validation" : [
        "입력값에 대한 유효성 체크를 모두 통과한 경우 true 로 반환합니다.",
        "입력값에 대한 유효성 체크를 하나라도 통과하지 못한 경우 실패 메시지가 출력된 후 false 로 반환합니다.",
        "mandatory, allowChar, ignoreChar, maxlength, minlength, maxByteLength, minByteLength 속성 순서로 유효성 체크가 실행됩니다.",
        "유효성 체크에 실패하면 실패한 속성에서 체크가 중단됩니다.",
        "유효성 체크에 실패한 컴포넌트가 포커스 됩니다.",
        "mandatory, allowChar, ignoreChar, maxlength, minlength, maxByteLength, minByteLength 속성이 한 개 이상 설정되어야 실행됩니다.",
        "displaymessage=true 인 경우 유효성 체크를 통과하지 못한 속성에 대한 실패 메시지가 출력되며, invalidMessage, invalidMessageFunc 속성으로 실패 메시지를 변경할 수 있습니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.check_validate = function (target) {
    let rtn = target.validate();

    wf_body_bottom.getObj("scwin").setReturnValue("return : " + rtn);
}



// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue(1234);
};


scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}


// target2
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("");
};


scwin.btn_validate2_onclick = function (e) {
    scwin.btn_setValue2_onclick();
    scwin.check_validate(target2);
}


